#### 类适配器
这一实现使用了继承机制：适配器同时继承两个对象的接口
这种方式仅能在支持多重继承的编程语言中实现
### c
```
#include <stdio.h>

// 旧播放器接口，支持播放MP3格式文件
typedef struct {
    void (*playMP3)(const char* filename);
} MP3Player;

// 新音频库接口，支持播放AAC格式文件
typedef struct {
    void (*playAAC)(const char* filename);
} AACPlayer;

// 实现AAC播放功能
void playAACFile(const char* filename) {
    printf("Playing AAC file: %s\n", filename);
}

// 创建一个适配器，使得AACPlayer看起来像MP3Player
typedef struct {
    MP3Player mp3Player;
    AACPlayer* aacPlayer;
} MP3ToAACAdapter;

// 适配器的播放方法
void playMP3UsingAdapter(const char* filename) {
    printf("Adapter converting MP3 request to AAC format...\n");
    MP3ToAACAdapter* adapter = (MP3ToAACAdapter*)filename;  // 注意：实际使用中，这种转换应通过上下文来完成，此处为简化示例
    adapter->aacPlayer->playAAC(filename);
}

int main() {
    // 创建AAC播放器实例
    AACPlayer aacPlayer = { playAACFile };

    // 创建适配器，将AAC播放器包装成MP3播放器
    MP3ToAACAdapter adapter = { { playMP3UsingAdapter }, &aacPlayer };

    // 使用适配器播放文件
    adapter.mp3Player.playMP3("example.aac");

    return 0;
}


```

