根据具体需求选择合适的队列实现方式。


# 3 
在C语言中，实现深度优先搜索（DFS）通常需要手动管理栈或递归调用。由于C语言没有内置的集合类型，我们通常使用数组或链表来模拟集合的功能。以下是使用递归和显式栈两种方式实现DFS的C语言示例。

### 1. 递归实现 DFS

递归实现是最直观的方式，利用函数调用栈来完成深度优先搜索。

#### 示例代码：

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_VERTICES 100

// 邻接表表示图
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* graph[MAX_VERTICES];
bool visited[MAX_VERTICES];

// 创建新节点
Node* createNode(int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

// 添加边
void addEdge(int src, int dest) {
    // 添加从src到dest的边
    Node* newNode = createNode(dest);
    newNode->next = graph[src];
    graph[src] = newNode;

    // 添加从dest到src的边（无向图）
    newNode = createNode(src);
    newNode->next = graph[dest];
    graph[dest] = newNode;
}

// 递归实现DFS
void dfs(int vertex) {
    visited[vertex] = true;
    printf("%d ", vertex);

    Node* temp = graph[vertex];
    while (temp) {
        int connectedVertex = temp->vertex;
        if (!visited[connectedVertex]) {
            dfs(connectedVertex);
        }
        temp = temp->next;
    }
}

int main() {
    int vertices = 6; // 图的顶点数
    for (int i = 0; i < vertices; i++) {
        graph[i] = NULL;
        visited[i] = false;
    }

    // 添加边
    addEdge(0, 1);
    addEdge(0, 2);
    addEdge(1, 3);
    addEdge(1, 4);
    addEdge(2, 5);

    printf("DFS Recursive: ");
    dfs(0); // 从顶点0开始DFS
    printf("\n");

    return 0;
}
```

#### 输出：

`DFS Recursive: 0 1 3 4 2 5`

### 2. 显式栈实现 DFS

显式栈实现使用一个栈来模拟递归过程，避免递归带来的函数调用开销。

#### 示例代码：

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_VERTICES 100

// 邻接表表示图
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* graph[MAX_VERTICES];
bool visited[MAX_VERTICES];

// 创建新节点
Node* createNode(int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

// 添加边
void addEdge(int src, int dest) {
    // 添加从src到dest的边
    Node* newNode = createNode(dest);
    newNode->next = graph[src];
    graph[src] = newNode;

    // 添加从dest到src的边（无向图）
    newNode = createNode(src);
    newNode->next = graph[dest];
    graph[dest] = newNode;
}

// 显式栈实现DFS
void dfsIterative(int start) {
    int stack[MAX_VERTICES], top = -1; // 使用数组模拟栈
    stack[++top] = start; // 将起始节点压入栈

    while (top != -1) {
        int vertex = stack[top--]; // 弹出栈顶元素
        if (!visited[vertex]) {
            visited[vertex] = true;
            printf("%d ", vertex);

            // 将当前节点的邻居节点压入栈
            Node* temp = graph[vertex];
            while (temp) {
                int connectedVertex = temp->vertex;
                if (!visited[connectedVertex]) {
                    stack[++top] = connectedVertex;
                }
                temp = temp->next;
            }
        }
    }
}

int main() {
    int vertices = 6; // 图的顶点数
    for (int i = 0; i < vertices; i++) {
        graph[i] = NULL;
        visited[i] = false;
    }

    // 添加边
    addEdge(0, 1);
    addEdge(0, 2);
    addEdge(1, 3);
    addEdge(1, 4);
    addEdge(2, 5);

    printf("DFS Iterative: ");
    dfsIterative(0); // 从顶点0开始DFS
    printf("\n");

    return 0;
}
```

#### 输出：

`DFS Iterative: 0 1 3 4 2 5`

