(cont'd) ### 二、基于链表的队列实现

#### 1. 定义队列节点和队列结构

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    int data;          // 存储队列元素
    struct Node *next; // 指向下一个节点
} Node;

typedef struct {
    Node *front;       // 队头指针
    Node *rear;        // 队尾指针
} Queue;
```

#### 2. 初始化队列

c复制

```c
void initQueue(Queue *queue) {
    queue->front = NULL; // 初始化队头指针
    queue->rear = NULL;  // 初始化队尾指针
}
```

#### 3. 判断队列是否为空

c复制

```c
bool isEmpty(Queue *queue) {
    return queue->front == NULL; // 如果队头指针为NULL，队列为空
}
```

#### 4. 入队操作

c复制

```c
bool enqueue(Queue *queue, int value) {
    Node *newNode = (Node *)malloc(sizeof(Node)); // 创建新节点
    if (newNode == NULL) {
        printf("Memory allocation failed. Cannot enqueue.\n");
        return false;
    }
    newNode->data = value; // 设置节点数据
    newNode->next = NULL;  // 新节点的下一个指针为NULL

    if (isEmpty(queue)) {
        queue->front = newNode; // 如果队列为空，队头指针指向新节点
    } else {
        queue->rear->next = newNode; // 否则，将新节点链接到队尾
    }
    queue->rear = newNode; // 更新队尾指针
    return true;
}
```

#### 5. 出队操作

c复制

```c
bool dequeue(Queue *queue, int *value) {
    if (isEmpty(queue)) {
        printf("Queue is empty. Cannot dequeue.\n");
        return false;
    }
    Node *temp = queue->front; // 保存当前队头节点
    *value = temp->data;       // 获取队头节点的数据
    queue->front = temp->next; // 更新队头指针
    if (queue->front == NULL) {
        queue->rear = NULL; // 如果队列为空，更新队尾指针
    }
    free(temp);              // 释放旧的队头节点
    return true;
}
```

#### 6. 获取队头元素

c复制

```c
bool peek(Queue *queue, int *value) {
    if (isEmpty(queue)) {
        printf("Queue is empty. Cannot peek.\n");
        return false;
    }
    *value = queue->front->data; // 返回队头节点的数据
    return true;
}
```

#### 7. 清空队列

c复制

```c
void clearQueue(Queue *queue) {
    while (!isEmpty(queue)) {
        int value;
        dequeue(queue, &value); // 逐个出队并释放内存
    }
}
```

#### 8. 测试代码

c复制

```c
int main() {
    Queue queue;
    initQueue(&queue);

    enqueue(&queue, 10);
    enqueue(&queue, 20);
    enqueue(&queue, 30);

    int value;
    if (peek(&queue, &value)) {
        printf("Front element: %d\n", value); // 输出：Front element: 10
    }

    if (dequeue(&queue, &value)) {
        printf("Dequeued element: %d\n", value); // 输出：Dequeued element: 10
    }

    if (isEmpty(&queue)) {
        printf("Queue is empty.\n");
    } else {
        printf("Queue is not empty.\n");
    }

    clearQueue(&queue); // 清空队列

    return 0;
}
```

### 总结

- **数组队列**：实现简单，性能高，但大小固定。适合队列大小已知且固定的应用场景。

- **链表队列**：动态扩展，灵活，但需要管理内存分配和释放。适合队列大小不确定或频繁变化的应用场景。


根据具体需求选择合适的队列实现方式。


# 3 
在C语言中，实现深度优先搜索（DFS）通常需要手动管理栈或递归调用。由于C语言没有内置的集合类型，我们通常使用数组或链表来模拟集合的功能。以下是使用递归和显式栈两种方式实现DFS的C语言示例。

### 1. 递归实现 DFS

递归实现是最直观的方式，利用函数调用栈来完成深度优先搜索。

#### 示例代码：

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_VERTICES 100

// 邻接表表示图
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* graph[MAX_VERTICES];
bool visited[MAX_VERTICES];

// 创建新节点
Node* createNode(int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

// 添加边
void addEdge(int src, int dest) {
    // 添加从src到dest的边
    Node* newNode = createNode(dest);
    newNode->next = graph[src];
    graph[src] = newNode;

    // 添加从dest到src的边（无向图）
    newNode = createNode(src);
    newNode->next = graph[dest];
    graph[dest] = newNode;
}

// 递归实现DFS
void dfs(int vertex) {
    visited[vertex] = true;
    printf("%d ", vertex);

    Node* temp = graph[vertex];
    while (temp) {
        int connectedVertex = temp->vertex;
        if (!visited[connectedVertex]) {
            dfs(connectedVertex);
        }
        temp = temp->next;
    }
}

int main() {
    int vertices = 6; // 图的顶点数
    for (int i = 0; i < vertices; i++) {
        graph[i] = NULL;
        visited[i] = false;
    }

    // 添加边
    addEdge(0, 1);
    addEdge(0, 2);
    addEdge(1, 3);
    addEdge(1, 4);
    addEdge(2, 5);

    printf("DFS Recursive: ");
    dfs(0); // 从顶点0开始DFS
    printf("\n");

    return 0;
}
```

#### 输出：

`DFS Recursive: 0 1 3 4 2 5`

### 2. 显式栈实现 DFS

显式栈实现使用一个栈来模拟递归过程，避免递归带来的函数调用开销。

#### 示例代码：

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_VERTICES 100

// 邻接表表示图
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* graph[MAX_VERTICES];
bool visited[MAX_VERTICES];

// 创建新节点
Node* createNode(int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

// 添加边
void addEdge(int src, int dest) {
    // 添加从src到dest的边
    Node* newNode = createNode(dest);
    newNode->next = graph[src];
    graph[src] = newNode;

    // 添加从dest到src的边（无向图）
    newNode = createNode(src);
    newNode->next = graph[dest];
    graph[dest] = newNode;
}

// 显式栈实现DFS
void dfsIterative(int start) {
    int stack[MAX_VERTICES], top = -1; // 使用数组模拟栈
    stack[++top] = start; // 将起始节点压入栈

    while (top != -1) {
        int vertex = stack[top--]; // 弹出栈顶元素
        if (!visited[vertex]) {
            visited[vertex] = true;
            printf("%d ", vertex);

            // 将当前节点的邻居节点压入栈
            Node* temp = graph[vertex];
            while (temp) {
                int connectedVertex = temp->vertex;
                if (!visited[connectedVertex]) {
                    stack[++top] = connectedVertex;
                }
                temp = temp->next;
            }
        }
    }
}

int main() {
    int vertices = 6; // 图的顶点数
    for (int i = 0; i < vertices; i++) {
