在C语言中，堆栈（Stack）是一种后进先出（LIFO）的数据结构。以下是用C语言实现堆栈的两种常见方式：基于数组的堆栈和基于链表的堆栈。

### 一、基于数组的堆栈实现

数组堆栈是一种简单且高效的实现方式，但它的大小是固定的。

#### 1. 定义堆栈结构

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_SIZE 100 // 堆栈的最大容量

typedef struct {
    int data[MAX_SIZE]; // 存储堆栈元素的数组
    int top;            // 指向堆栈顶部的指针
} Stack;
```

#### 2. 初始化堆栈

c复制

```c
void initStack(Stack *stack) {
    stack->top = -1; // 初始化时，堆栈为空，top指向-1
}
```

#### 3. 判断堆栈是否为空

c复制

```c
bool isEmpty(Stack *stack) {
    return stack->top == -1; // 如果top为-1，堆栈为空
}
```

#### 4. 判断堆栈是否已满

c复制

```c
bool isFull(Stack *stack) {
    return stack->top == MAX_SIZE - 1; // 如果top等于数组最大索引，堆栈已满
}
```

#### 5. 入栈操作

c复制

```c
bool push(Stack *stack, int value) {
    if (isFull(stack)) {
        printf("Stack is full. Cannot push.\n");
        return false;
    }
    stack->data[++stack->top] = value; // top加1后，将值存入堆栈
    return true;
}
```

#### 6. 出栈操作

c复制

```c
bool pop(Stack *stack, int *value) {
    if (isEmpty(stack)) {
        printf("Stack is empty. Cannot pop.\n");
        return false;
    }
    *value = stack->data[stack->top--]; // 取出堆栈顶部的值，top减1
    return true;
}
```

#### 7. 获取堆栈顶部元素

c复制

```c
bool peek(Stack *stack, int *value) {
    if (isEmpty(stack)) {
        printf("Stack is empty. Cannot peek.\n");
        return false;
    }
    *value = stack->data[stack->top]; // 返回堆栈顶部的值，但不修改top
    return true;
}
```

#### 8. 测试代码

c复制

```c
int main() {
    Stack stack;
    initStack(&stack);

    push(&stack, 10);
    push(&stack, 20);
    push(&stack, 30);

    int value;
    if (peek(&stack, &value)) {
        printf("Top element: %d\n", value); // 输出：Top element: 30
    }

    if (pop(&stack, &value)) {
        printf("Popped element: %d\n", value); // 输出：Popped element: 30
    }

    if (isEmpty(&stack)) {
        printf("Stack is empty.\n");
    } else {
        printf("Stack is not empty.\n");
    }

    return 0;
}
```

### 二、基于链表的堆栈实现

链表堆栈可以动态扩展，但需要管理内存分配和释放。

#### 1. 定义堆栈节点和堆栈结构

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    int data;          // 存储堆栈元素
    struct Node *next; // 指向下一个节点
} Node;

typedef struct {
    Node *top; // 指向堆栈顶部的指针
} Stack;
```

#### 2. 初始化堆栈

c复制

```c
void initStack(Stack *stack) {
    stack->top = NULL; // 初始化时，堆栈为空，top指向NULL
}
```

#### 3. 判断堆栈是否为空

c复制

```c
bool isEmpty(Stack *stack) {
    return stack->top == NULL; // 如果top为NULL，堆栈为空
}
```

#### 4. 入栈操作

c复制

```c
bool push(Stack *stack, int value) {
    Node *newNode = (Node *)malloc(sizeof(Node)); // 创建新节点
    if (newNode == NULL) {
        printf("Memory allocation failed. Cannot push.\n");
        return false;
    }
    newNode->data = value; // 设置节点数据
    newNode->next = stack->top; // 新节点指向当前顶部节点
    stack->top = newNode; // 更新堆栈顶部指针
    return true;
}
```

#### 5. 出栈操作

c复制

```c
bool pop(Stack *stack, int *value) {
    if (isEmpty(stack)) {
        printf("Stack is empty. Cannot pop.\n");
        return false;
    }
    Node *temp = stack->top; // 保存当前顶部节点
    *value = temp->data;     // 获取顶部节点的数据
    stack->top = temp->next; // 更新堆栈顶部指针
    free(temp);              // 释放旧的顶部节点
    return true;
}
```

#### 6. 获取堆栈顶部元素

c复制

```c
bool peek(Stack *stack, int *value) {
    if (isEmpty(stack)) {
        printf("Stack is empty. Cannot peek.\n");
        return false;
    }
    *value = stack->top->data; // 返回堆栈顶部的值
    return true;
}
```

#### 7. 清空堆栈

c复制

```c
void clearStack(Stack *stack) {
    while (!isEmpty(stack)) {
        int value;
        pop(stack, &value); // 逐个出栈并释放内存
    }
}
```

#### 8. 测试代码

c复制

```c
int main() {
    Stack stack;
    initStack(&stack);

    push(&stack, 10);
    push(&stack, 20);
    push(&stack, 30);

    int value;
    if (peek(&stack, &value)) {
        printf("Top element: %d\n", value); // 输出：Top element: 30
    }

    if (pop(&stack, &value)) {
        printf("Popped element: %d\n", value); // 输出：Popped element: 30
    }

    if (isEmpty(&stack)) {
        printf("Stack is empty.\n");
    } else {
        printf("Stack is not empty.\n");
    }

    clearStack(&stack); // 清空堆栈

    return 0;
}
```

### 总结

- **数组堆栈**：实现简单，性能高，但大小固定。

- **链表堆栈**：动态扩展，灵活，但需要管理内存分配和释放。


根据具体需求选择合适的堆栈实现方式。






# 1 如果栈中元素类型不同



如果栈中的元素类型不同，可以使用C语言中的**联合体（Union）**和**枚举（Enum）**来实现一个通用的多类型栈。联合体可以存储多种类型的数据，而枚举可以用来标记当前存储的数据类型。

以下是一个基于链表实现的多类型栈的示例代码：

### 1. 定义数据类型和节点结构

c复制

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// 定义数据类型枚举
typedef enum {
    INT,
    FLOAT,
    CHAR,
    STRING
} DataType;

// 定义联合体，用于存储不同类型的数据
typedef union {
    int intVal;
    float floatVal;
    char charVal;
    char *stringVal;
} DataUnion;

// 定义链表节点
typedef struct Node {
    DataType type;       // 当前节点的数据类型
    DataUnion data;      // 联合体，存储实际数据
    struct Node *next;   // 指向下一个节点
} Node;

// 定义栈结构
typedef struct {
    Node *top;           // 指向栈顶的指针
} Stack;
```

### 2. 初始化栈

c复制

```c
void initStack(Stack *stack) {
    stack->top = NULL;   // 初始化栈顶指针为NULL
}
```

### 3. 判断栈是否为空

c复制

```c
bool isEmpty(Stack *stack) {
    return stack->top == NULL;  // 如果栈顶指针为NULL，栈为空
}
```

### 4. 入栈操作

c复制

```c
bool push(Stack *stack, DataType type, DataUnion data) {
    Node *newNode = (Node *)malloc(sizeof(Node));  // 创建新节点
    if (newNode == NULL) {
        printf("Memory allocation failed. Cannot push.\n");
        return false;
    }
    newNode->type = type;  // 设置数据类型
    newNode->data = data;  // 设置数据值
    newNode->next = stack->top;  // 新节点指向当前栈顶
    stack->top = newNode;  // 更新栈顶指针
    return true;
}
```

### 5. 出栈操作

c复制

```c
bool pop(Stack *stack, DataType *type, DataUnion *data) {
    if (isEmpty(stack)) {
        printf("Stack is empty. Cannot pop.\n");
        return false;
    }
    Node *temp = stack->top;  // 保存当前栈顶节点
    *type = temp->type;       // 获取数据类型
    *data = temp->data;       // 获取数据值
    stack->top = temp->next;  // 更新栈顶指针
    free(temp);               // 释放旧的栈顶节点
    return true;
}
```

